package ovid/parse

import ovid/io

func GoalDecl(io *ovid/io.Cap, name i64, n i64, next *Decl) *Decl {
  var d *Decl = ovid/io.Alloc(io, sizeof(Decl)) as *Decl
  d.namep = name
  d.namen = n
  d.next = next
  return d
}

func TestGoalLastDecl(io *ovid/io.Cap) i64 {
  var c *Decl = GoalDecl(io, strptr("c"), 1, 0 as *Decl)
  var b *Decl = GoalDecl(io, strptr("b"), 1, c)
  var a *Decl = GoalDecl(io, strptr("a"), 1, b)
  if LastDecl(a) != c || LastDecl(c) != c {
    return 1
  }
  if LastDecl(0 as *Decl) != 0 as *Decl {
    return 2
  }
  return 0
}

func TestGoalLookupDecl(io *ovid/io.Cap) i64 {
  var c *Decl = GoalDecl(io, strptr("cc"), 2, 0 as *Decl)
  var b *Decl = GoalDecl(io, strptr("bb"), 2, c)
  var a *Decl = GoalDecl(io, strptr("aa"), 2, b)
  if LookupDecl(a, strptr("bb"), 2) != b || LookupDecl(a, strptr("cc"), 2) != c {
    return 1
  }
  if LookupDecl(a, strptr("b"), 1) != 0 as *Decl || LookupDecl(0 as *Decl, strptr("aa"), 2) != 0 as *Decl {
    return 2
  }
  return 0
}

